package com.sisge.ms.entity;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="roles") public class Rol { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String nombre; private String descripcion; @Column(name="global_role",nullable=false) private boolean globalRol; @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="rol_permisos",joinColumns=@JoinColumn(name="rol_id"),inverseJoinColumns=@JoinColumn(name="permiso_id")) private Set<Permission> permisos=new HashSet<>();
 public Long getId(){return id;} public String getNombre(){return nombre;} public void setNombre(String n){nombre=n;} public String getDescripcion(){return descripcion;} public void setDescripcion(String d){descripcion=d;} public boolean isGlobalRole(){return globalRol;} public void setGlobalRole(boolean v){globalRol=v;} public Set<Permission> getPermisos(){return permisos;} public void setPermisos(Set<Permission> p){permisos=new HashSet<>(p);} }
